bool TESObjectREFR::TESObjectREFR_ReplaceModel()
{
    TESBoundObject* pbase = pObjectReference;
    TESCreature* pcreature = (TESCreature*)pbase;
    TESNPC* pnpc = (TESNPC*)pbase;
    bool breturn = false;
    void* bipedPtr = GetBiped();
    Animation* panim = GetAnimation();
    if (panim)
        panim->ResetTransforms();
    NiAVObject* p3D = Get3D();
    switch (pObjectReference->cFormType) {
    case 0x2a:
        if (bipedPtr)
            pnpc->ReplaceRefModel(this);
        breturn = true;
        break;
    case 0x2b:
        if (p3D) {
            if (IsActor())
                ((Actor*)this)->GetCurrentPackage();
            pcreature->PrepareWornItems(this);
            FileNode* pcreatureFileList = pcreature->kCreatureFileList.GetHead();
            while (pcreatureFileList && !pcreatureFileList->IsEmpty()) {
                char pfullPathFilename[260];
                TESModel* pmodel = GetTESModel();
                strcpy_s(pfullPathFilename, 260, pmodel ? pmodel->GetModel() : 0);
                char* pslash = strrchr(pfullPathFilename, 0x5c);
                strcpy_s(pslash + 1, 260 - (pslash - pfullPathFilename) - 1, pcreatureFileList->GetItem());
                NiAVObject* pcreatureSkin = g_pModelLoader->LoadFile(pfullPathFilename, 3, 1, 0, 0, 0);
                if (pcreatureSkin) {
                    BSCloningProcess cloneData(GetScale());
                    NiPtr<NiObject> spdeepCopy;
                    NiObject* pclone;
                    if (HasMorpherController(pcreatureSkin)) {
                        spdeepCopy = g_pTES->CreateDeepCopy(pcreatureSkin, &cloneData);
                        pclone = spdeepCopy;
                    } else
                        pclone = pcreatureSkin->Clone(&cloneData);
                    bool bskinned = HasSkinnedGeometry(pclone);
                    NiAVObject* pskeletonObj = FindBoneByName(p3D, g_strBip01, true);
                    if (bskinned && pskeletonObj) {
                        NiAVObject* pparent;
                        {
                            NiFixedString kName(DAT_00dc01d0);
                            pparent = pskeletonObj->GetObjectByName(kName);
                        }
                        if (pparent)
                            pparent->AttachChild((NiAVObject*)pclone, true);
                        else
                            pskeletonObj->GetParent()->AttachChild((NiAVObject*)pclone, true);
                        AttachToSkeleton(p3D, (NiAVObject*)pclone, false, true);
                    } else
                        AttachNode(p3D, (NiAVObject*)pclone, 0, 0, -1, 0);
                }
                pcreatureFileList = pcreatureFileList->GetNext();
            }
        }
        breturn = true;
        break;
    }
    if (!breturn)
        breturn = pObjectReference->ReplaceModel();
    return breturn;
}

