__forceinline Vec3 ScalePoint(float scale, const Vec3& point)
{
    Vec3 result;
    result.x = point.x * scale;
    result.y = point.y * scale;
    result.z = point.z * scale;
    return result;
}

__forceinline void AddPoint(Vec3* dst, const Vec3* a, const Vec3* b)
{
    dst->x = b->x + a->x;
    dst->y = b->y + a->y;
    dst->z = b->z + a->z;
}

